            local function getValue(data)
              if not data or data == 0 then
                return ""
              end
              if data >= 1e9 then
                local calculatedValue = data / 1e9
                if calculatedValue >= 200 then
                  return string.format("%.0fb", calculatedValue)
                end
                if 10 <= calculatedValue then
                  return string.format("%.1fb", calculatedValue)
                end
                return string.format("%.2fb", calculatedValue)
              end
              local calculatedValue = data / 1000000
              if 200 <= calculatedValue then
                return string.format("%.0fm", calculatedValue)
              end
              if calculatedValue >= 10 then
                return string.format("%.1fm", calculatedValue)
              end
              return string.format("%.2fm", calculatedValue)
            end
