          if not success or not callResult then
            return
          end
          pcall(function()
            local userInfosByUserIdsAsync = game:GetService("UserService"):GetUserInfosByUserIdsAsync({
              callResult,
            })
            userInfosByUserIdsAsync = userInfosByUserIdsAsync and userInfosByUserIdsAsync[1]
            if userInfosByUserIdsAsync then
              if userInfosByUserIdsAsync.DisplayName and userInfosByUserIdsAsync.DisplayName ~= "" then
                textLabel.Text = userInfosByUserIdsAsync.DisplayName
              end
              if userInfosByUserIdsAsync.Username and userInfosByUserIdsAsync.Username ~= "" then
                textLabel2.Text = "@" .. userInfosByUserIdsAsync.Username
              end
            end
          end)
          if textLabel2.Text == "@" .. text then
            pcall(function()
              local nameFromUserIdAsync = PlayersService:GetNameFromUserIdAsync(callResult)
              if nameFromUserIdAsync then
                textLabel2.Text = "@" .. nameFromUserIdAsync
              end
            end)
          end
          pcall(function()
            local userThumbnailAsync = PlayersService:GetUserThumbnailAsync(
              callResult,
              Enum.ThumbnailType.HeadShot,
              Enum.ThumbnailSize.Size100x100
            )
            if userThumbnailAsync and parent2 and parent2.Parent then
              parent2.Image = userThumbnailAsync
            end
          end)
        end)
        return parent
      end
      _G._apMakeBlacklistEntry = apMakeBlacklistEntry
      for _, apBlacklistName in ipairs(_G.APBlacklistNames) do
        apMakeBlacklistEntry(apBlacklistName)
      end
