    if not label.Text or label.Text == "" then
      return
    end
    if label.Text:lower():find("you%s+stole%s+") then
      local text = "_" .. label.Text
      local text2 = label:GetDebugId() .. text
      if not items[text2] then
        items[text2] = tick()
        if _G.autoKickEnabledTime < tick() then
          isEnabled = true
          local match = (label.Text:match("[Yy]ou%s+stole%s+(.+)") or "something")
