            :gsub("%s*%([Ee]rror%s+[Cc]ode:?%s*%d+%)%s*", "")
            :match("^%s*(.-)%s*$")
          if _G._xenPSLinkCode then
            pcall(function()
              if _G.triggerJoinPS then
                _G.triggerJoinPS()
              end
            end)
          else
            _G.KICK_IN_PROGRESS = true
            localPlayer:Kick("You have successfully stolen " .. match)
