        if child:IsA("Model") then
          pcall(function()
            position = child:GetPivot().Position
          end)
        elseif child:IsA("BasePart") then
          position = child.Position
        end
        if position then
          table.insert(items, {
            Object = child,
            Height = position.Y,
          })
        end
      end
