local function row(text,y,getter,setter) local b=corner(mk("TextButton",root,{Position=UDim2.fromOffset(12,y),Size=UDim2.new(1,-24,0,28),BackgroundColor3=Color3.fromRGB(42,42,42),BorderSizePixel=0,Text="",Font=UIFB,TextSize=11,TextColor3=Color3.fromRGB(255,255,255),AutoButtonColor=false,Active=true,ZIndex=21}),6); local function paint() local on=getter(); b.Text=text..(on and "  ON" or "  OFF"); b.BackgroundColor3=on and Color3.fromRGB(235,235,235) or Color3.fromRGB(42,42,42); b.TextColor3=on and Color3.fromRGB(0,0,0) or Color3.fromRGB(255,255,255) end; b.MouseButton1Click:Connect(function() setter(); paint() end); paint(); return b end
		row("INVISIBLE STEAL",48,function() return _G.StickyInvisActive==true end,function() if type(_G.StickyInvisToggle)=="function" then pcall(_G.StickyInvisToggle) elseif type(_G.StickyInvisStart)=="function" then if _G.StickyInvisActive then pcall(_G.StickyInvisStop) else pcall(_G.StickyInvisStart) end end end)
		row("AUTO RECOVER",80,function() return _G.StickyInvisAutoRecover==true end,function() _G.StickyInvisAutoRecover=not (_G.StickyInvisAutoRecover==true); if type(saveTpSettings)=="function" then pcall(saveTpSettings) end end)
		row("AUTO INVISIBLE ON STEAL",112,function() return _G.StickyInvisAuto==true end,function() _G.StickyInvisAuto=not (_G.StickyInvisAuto==true); if type(_G.StickyInvisSync)=="function" then pcall(_G.StickyInvisSync) end; if type(saveTpSettings)=="function" then pcall(saveTpSettings) end end)
		local function valueLine(title,y,key,minv,maxv,step,suffix) local l=mk("TextLabel",root,{Position=UDim2.fromOffset(12,y),Size=UDim2.new(1,-100,0,22),BackgroundTransparency=1,Text="",Font=UIFB,TextSize=11,TextColor3=Color3.fromRGB(255,255,255),TextXAlignment=Enum.TextXAlignment.Left,ZIndex=22}); local function paint() l.Text=title..": "..tostring(_G[key] or minv)..suffix end; local function adj(d) _G[key]=math.clamp((tonumber(_G[key]) or minv)+d,minv,maxv); if key=="StickyInvisAngle" then _G.InvisStealAngle=_G[key] else _G.SinkSliderValue=_G[key] end; saveTpSettings(); paint() end; for _,spec in ipairs({{"−",200,-step},{"+",234,step}}) do local b=corner(mk("TextButton",root,{Position=UDim2.fromOffset(spec[2],y),Size=UDim2.fromOffset(30,22),BackgroundColor3=Color3.fromRGB(42,42,42),BorderSizePixel=0,Text=spec[1],Font=UIFB,TextSize=14,TextColor3=Color3.fromRGB(255,255,255),AutoButtonColor=false,Active=true,ZIndex=22}),5); b.MouseButton1Click:Connect(function() adj(spec[3]) end) end; paint() end
			valueLine("ROTATION",146,"StickyInvisAngle",0,360,5,"°"); valueLine("DEPTH",172,"StickyInvisDepth",0,10,0.5,"")
			local walkBaseButton=corner(mk("TextButton",root,{Name="WalkToBaseButton",Position=UDim2.fromOffset(12,204),Size=UDim2.new(1,-24,0,28),BackgroundColor3=Color3.fromRGB(235,235,235),BorderSizePixel=0,Text="WALK TO BASE",Font=UIFB,TextSize=11,TextColor3=Color3.fromRGB(0,0,0),AutoButtonColor=false,Active=true,ZIndex=22}),6)
			local walkBaseRun=0
			local pathfindingService=game:GetService("PathfindingService")
			local function findOwnedBase()
				local plots=workspace:FindFirstChild("Plots")
				if not plots then return nil end
				local player=game:GetService("Players").LocalPlayer
				local playerName=tostring(player and player.Name or ""):lower()
				local displayName=tostring(player and player.DisplayName or ""):lower()
				for _,plot in ipairs(plots:GetChildren()) do
					local owner=plot:GetAttribute("Owner") or plot:GetAttribute("OwnerName")
					local ownerId=plot:GetAttribute("OwnerUserId")
					local owned=(tostring(owner or ""):lower()==playerName)
						or (tonumber(ownerId) and player and tonumber(ownerId)==player.UserId)
						or tostring(plot.Name):lower()==playerName
					local sign=plot:FindFirstChild("PlotSign")
					if not owned and sign and playerName~="" then
						for _,obj in ipairs(sign:GetDescendants()) do
							if obj:IsA("TextLabel") then
								local text=tostring(obj.Text or ""):lower()
								if text:find(playerName,1,true) or (displayName~="" and text:find(displayName,1,true)) then owned=true; break end
							end
						end
					end
					if owned then return plot end
				end
				return nil
			end
			local function getBaseSpawnPosition(plot)
				local exactSpawn,namedSpawn,mainPart
				for _,obj in ipairs(plot:GetDescendants()) do
					if obj:IsA("SpawnLocation") then exactSpawn=exactSpawn or obj end
					if obj:IsA("BasePart") then
						local name=obj.Name:lower():gsub("[%s_%-]","")
						if name=="mainrootpart" then mainPart=mainPart or obj end
						if not namedSpawn and (name=="spawn" or name=="spawnpoint" or name=="playerspawn" or name=="basespawn" or name=="spawnlocation") then namedSpawn=obj end
					end
				end
				local target=exactSpawn or namedSpawn or mainPart or plot:FindFirstChildWhichIsA("BasePart",true)
				if not target then return nil end
				return target.Position+Vector3.new(0,target.Size.Y*0.5+3,0)
			end
			local function startWalkToBase()
				walkBaseRun+=1
				local thisRun=walkBaseRun
				walkBaseButton.Text="FINDING BASE..."
				task.spawn(function()
					local player=game:GetService("Players").LocalPlayer
					local plot=findOwnedBase()
					local goal=plot and getBaseSpawnPosition(plot)
					local character=player and player.Character
					local humanoid=character and character:FindFirstChildOfClass("Humanoid")
					local rootPart=character and character:FindFirstChild("HumanoidRootPart")
					if not plot or not goal or not humanoid or not rootPart then
						walkBaseButton.Text="BASE NOT FOUND"
						task.delay(2,function() if walkBaseRun==thisRun and walkBaseButton.Parent then walkBaseButton.Text="WALK TO BASE" end end)
						return
					end
					if _G.StickyTPBusy==true or player:GetAttribute("Stealing")==true then
						walkBaseButton.Text="BUSY — TRY LATER"
						task.delay(2,function() if walkBaseRun==thisRun and walkBaseButton.Parent then walkBaseButton.Text="WALK TO BASE" end end)
						return
					end
					local arrived=false
					for attempt=1,3 do
						if walkBaseRun~=thisRun or player.Character~=character then break end
						local path
						local ok=pcall(function()
							path=pathfindingService:CreatePath({AgentRadius=2,AgentHeight=5,AgentCanJump=true,AgentCanClimb=true,WaypointSpacing=4})
							path:ComputeAsync(rootPart.Position,goal)
						end)
						if not ok or not path or path.Status~=Enum.PathStatus.Success then break end
						local routeOk=true
						local waypoints=path:GetWaypoints()
						for _,waypoint in ipairs(waypoints) do
							if walkBaseRun~=thisRun or player.Character~=character or not rootPart.Parent then routeOk=false; break end
							if waypoint.Action==Enum.PathWaypointAction.Jump then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
							humanoid:MoveTo(waypoint.Position)
							local reached=nil
							local connection=humanoid.MoveToFinished:Connect(function(success) reached=success end)
							local started=os.clock()
							while reached==nil and os.clock()-started<9 and walkBaseRun==thisRun and player.Character==character do task.wait(0.1) end
							connection:Disconnect()
							if reached~=true then routeOk=false; break end
						end
						if routeOk and rootPart.Parent and (rootPart.Position-goal).Magnitude<=7 then arrived=true; break end
					end
					if walkBaseRun==thisRun and walkBaseButton.Parent then
						walkBaseButton.Text=arrived and "ARRIVED AT BASE" or "NO PATH FOUND"
						task.delay(2,function() if walkBaseRun==thisRun and walkBaseButton.Parent then walkBaseButton.Text="WALK TO BASE" end end)
					end
				end)
			end
			walkBaseButton.MouseButton1Click:Connect(startWalkToBase)
		task.spawn(function() while root.Parent do if _G.StickyInvisAutoRecover==true then local plr=game:GetService("Players").LocalPlayer; local ch=plr and plr.Character; local hum=ch and ch:FindFirstChildOfClass("Humanoid"); if hum then local state=hum:GetState(); if state==Enum.HumanoidStateType.Ragdoll or state==Enum.HumanoidStateType.FallingDown or state==Enum.HumanoidStateType.Physics or state==Enum.HumanoidStateType.Dead then pcall(function() hum.PlatformStand=false; hum:ChangeState(Enum.HumanoidStateType.GettingUp) end) end end end; task.wait(0.5) end end)
		_G.StickyToggleExtrasUI=function() _G.StickySetInvisibleStealUI(not invSg.Enabled) end
	end

